import 'package:flutter/material.dart';
void main()=>runApp(const QismatApp());
class QismatApp extends StatelessWidget{const QismatApp({super.key});@override Widget build(BuildContext context)=>MaterialApp(debugShowCheckedModeBanner:false,title:'Qismat',theme:ThemeData(colorScheme:ColorScheme.fromSeed(seedColor:const Color(0xFF8F2948)),useMaterial3:true),home:const HomeScreen());}
class HomeScreen extends StatefulWidget{const HomeScreen({super.key});@override State<HomeScreen> createState()=>_HomeScreenState();}
class _HomeScreenState extends State<HomeScreen>{int index=0;final pages=const[_Page('Discover','Your recommended matches will appear here.'),_Page('Search','Filter profiles by your partner preferences.'),_Page('Interests','Sent and received interests.'),_Page('Messages','Chat becomes available after mutual acceptance.'),_Page('Profile','Complete and verify your matrimonial profile.')];@override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('Qismat')),body:pages[index],bottomNavigationBar:NavigationBar(selectedIndex:index,onDestinationSelected:(i)=>setState(()=>index=i),destinations:const[NavigationDestination(icon:Icon(Icons.favorite_outline),label:'Discover'),NavigationDestination(icon:Icon(Icons.search),label:'Search'),NavigationDestination(icon:Icon(Icons.handshake_outlined),label:'Interests'),NavigationDestination(icon:Icon(Icons.chat_bubble_outline),label:'Messages'),NavigationDestination(icon:Icon(Icons.person_outline),label:'Profile')]));}
class _Page extends StatelessWidget{final String title,subtitle;const _Page(this.title,this.subtitle);@override Widget build(BuildContext context)=>Center(child:Padding(padding:const EdgeInsets.all(28),child:Column(mainAxisSize:MainAxisSize.min,children:[Text(title,style:Theme.of(context).textTheme.headlineMedium),const SizedBox(height:12),Text(subtitle,textAlign:TextAlign.center)])));}
